def round_half_to_even(n):
    """

    # Import necessary modules here
    from math import log, floor

    # Handle negative numbers
    if n < 0:
        n = -n

    # If the number is a whole number, return the same number
    if n % 1 == 0:
        return n

    # Get the exponent of the number
    exponent = int(log(n, 10))

    # If the exponent is odd, round up to the next even number
    if exponent % 2 == 1:
        return 10 ** exponent * 2 * round(n / (10 ** exponent * 2))

    # Otherwise, round down to the next even number
    return 10 ** exponent * 2 * round(n / (10 ** exponent * 2))

    """

    # Calculate the number of digits after the decimal point
    num_digits = len(str(n).split('.')[1])

    # If the number has more than 15 digits after the decimal point, round to the nearest 10^15
    if num_digits > 15:
        return round(n / 10 ** (num_digits - 15)) * 10 ** 15

    # If the number has between 14 and 10 digits after the decimal point, round to the nearest 10^10
    elif num_digits > 10:
        return round(n / 10 ** (num_digits - 10)) * 10 ** 10

    # If the number has between 9 and 14 digits after the decimal point, round to the nearest 10^9
    elif num_digits > 9:
        return round(n / 10 ** (num_digits - 9)) * 10 ** 9

    # If the number has between 8 and 9 digits after the decimal point, round to the nearest 10^8
    elif num_digits > 8:
        return round(n / 10 ** (num_digits - 8)) * 10 ** 8

