    else:
        master, slave = None, None

    # Create a process for the xargs command
    process = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True if os.name == 'nt' else False)

    # Loop through each argument and send it to the xargs process
    for arg in varargs:
        process.stdin.write(arg.encode() + b'\n')

    # Close the xargs process' stdin, and wait for it to terminate
    process.stdin.close()
    process.wait()

    # Return the exit code and output of the xargs process
