def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent

    Args:
        classes (list[type]): A list of base classes

    Returns:
        tuple[type]: A tuple of the minimal number of base classes
    """
    bases = []
    for cls in classes:
        if cls in bases:
            continue
        while True:
            new_bases = []
            for base in bases:
                if issubclass(base, cls):
                    new_bases.append(base)
            if len(new_bases) == len(bases):
                break
            bases = new_bases
        bases.append(cls)
    return tuple(bases)

