    if x < minx or x > maxx or y < miny or y > maxy:
        return
    self.histogram[x][y] += weight
    self.minx = min(self.minx, x)
    self.maxx = max(self.maxx, x)
    self.miny = min(self.miny, y)
    self.maxy = max(self.maxy, y)

