            default observer schema
    """

    for resource in app.spec.manifest:
        if not resource.observer_schema:
            observer_schema = {}
            for attribute in resource.__dict__.keys():
                attribute_type = getattr(resource, attribute).__class__.__name__
                if attribute == "id" or attribute == "cls":
                    continue
                elif attribute_type in _DEFAULT_OBSERVER_SCHEMAS:
                    observer_schema[attribute] = _DEFAULT_OBSERVER_SCHEMAS[attribute_type]
            if len(observer_schema) > 0:
                resource.observer_schema = observer_schema

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :param params: The set of in-style parameters.
    :return: The formatted SQL query and the set of out-style parameters.
    """
    formatted_sql = ''
    out_params = []

    # Handle the in-style parameters
    if self.in_style is not None:
        # When the in-style is named, params should be a mapping
        if isinstance(params, Mapping):
            for key, value in params.items():
                # Find the parameter's index and format it
                index = sql.find('?', 0, sql.find(key.upper()))
                if index != -1:
                    formatted_sql += sql[:index] + self.param_format.format(index + 1) + sql[index + 1:]
                    out_params.append(value)
        # When the in-style is ordinal, params should be a sequence
        elif isinstance(params, Sequence):
            for parameter, value in enumerate(params):
                # Find the parameter's index and format it
                index = sql.find(parameter + 1)
                if index != -1:
                    formatted_sql += sql[:index] + self.param_format.format(parameter + 1) + sql[index + 1:]
                    out_params.append(value)

    # Handle the out-style parameters
    if self.out_style is not None:
        # When the out-style is named, put the key-value pairs in a dict
        if self.out_style == 'named':
            out_params = {self.out_format.format(i + 1): value for i, value in enumerate(out_params)}
        # When the out-style is ordinal, put the values in a list
        elif self.out_style == 'ordinal':
            out_params = [value for value in out_params]

    return formatted_sql, out_params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
"""
Convert the SQL query to use out-style parameters instead of in-style parameters.

*sql* (:class:`str` or :class:`bytes`) is the SQL query.

*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`) contains the set of in-style parameters. It maps each parameter (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style` is a named parameter style, then *params* must be a :class:`~collections.abc.Mapping`. If :attr:`.SQLParams.in_style` is an ordinal parameter style, then *params* must be a :class:`~collections.abc.Sequence`.

Return a :class:`tuple` containing:

- The formatted SQL query (:class:`str` or :class:`bytes`).

- The set of converted out-style parameters (:class:`dict` or :class:`list`).

"""

# check if input parameters are valid
if not isinstance(sql, (str, bytes)):
    raise ValueError("sql must be a string or bytes")
if not isinstance(params, (dict, list)):
    raise ValueError("params must be a dictionary or a list")

# convert in-style parameters to out-style parameters
out_params = {}
if isinstance(params, dict):
    for k, v in params.items():
        if isinstance(k, str):
            out_params[k] = v
        else:
            out_params[":%d" % k] = v
elif isinstance(params, list):
    for i, v in enumerate(params):
        out_params["(:%d)" % i] = v

# format SQL query with out-style parameters
formatted_sql = sql.replace("?", "%s")

return formatted_sql, out_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """

    # Check that path is a string
    if not isinstance(path, str):
        raise ValueError("Invalid type for argument 'path'. Expected 'str', got '{}'".format(type(path)))

    # Check that path is a valid directory
    if not os.path.isdir(path):
        raise ValueError("Invalid path. Must be a valid directory, got '{}'".format(path))

    # Check that OCFL object exists at path
    if not os.path.exists(os.path.join(path, 'ocfl_object.json')):
        raise ValueError("OCFL object does not exist at path '{}'".format(path))

    # Check that pyfs is installed
    try:
        import pyfs
    except ModuleNotFoundError:
        raise ValueError("Could not validate OCFL object at path '{}' because pyfs is not installed".format(path))

    # Validate OCFL object
    with pyfs.Fs(path) as fs:
        try:
            fs.validate_ocfl()
        except pyfs.exceptions.OCFLValidationError as e:
            print('OCFL validation error: {}'.format(e))
            return False

    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """

    # Check if the object is at the pyfs root
    if path == '/':
        if not self.version:
            self.version = Version()
        elif self.version.ls() is not {}:
            return False
        else:
            return True

    # Check if the object is at the filesystem root
    elif os.path.exists(path):
        if not self.version:
            self.version = Version()
        elif self.version.ls() is not {}:
            return False
        else:
            return True

    # Check if the object is a valid version
    else:
        version_id = path.split('/')[2]
        try:
            self.version = Version(version_id)
        except (FileNotFoundError, IndexError):
            return False

        if self.version.validate():
            return True
        else:
            return False

def status_str(self, prefix=''):
        """Return string of validator status, with optional prefix."""
        # Check if the validator has a parent and if it is valid
        if self.parent is not None and not self.parent.is_valid():
            return prefix + 'Validator has invalid parent'

        # Check if the validator has any constraints
        if not self.constraints:
            return prefix + 'Validator has no constraints'

        # Check if all constraints are satisfied
        for constraint in self.constraints:
            if not constraint.is_satisfied():
                return prefix + 'Validator has unsatisfied constraint: ' + str(constraint)

        # Check if the validator has any child validators
        if self.child_validators is not None:
            for child_validator in self.child_validators:
                child_status = child_validator.status_str(prefix + '  ')
                if child_status is not None:
                    return child_status

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    statuses = []
    for level in self.levels:
        if level.status:
            statuses.append(level.status)
    if not statuses:
        return f"{prefix}No errors."
    else:
        return f"{prefix}{', '.join(statuses)}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    msg = []
    if self.code == 0:
        msg.append(f"{prefix}Validation succeeded: no issues detected")
    elif self.code == 1:
        msg.append(f"{prefix}Validation succeeded: partially successful")
    else:
        msg.append(f"{prefix}Validation failed: {self.code} error(s) found")
    if self.error_log:
        msg.append(f"{prefix}Detail:")
        for line in self.error_log.splitlines():
            msg.append(f"{prefix}{line}")
    return "\n".join(msg)

