    """Check all digests in manifest that are needed are present and used.

    Args:
        manifest_files (list of str): The list of manifest files to check.
        digests_used (set of str): The set of digests that are actually used in the project.

    Raises:
        ValueError: If a digest in the manifest is not used in the project.
    """

    needed_digests = set()

    for file_path in manifest_files:
        with open(file_path, "r") as f:
            for line in f:
                if line.startswith("digest:"):
                    digest = line.split(" ")[1]
                    if digest not in digests_used:
                        needed_digests.add(digest)

    for digest in needed_digests:
        if digest not in digests_used:
            raise ValueError(f"Digest {digest} is required in the manifest but has not been used in the project.")

