        digests_used (dict): A dictionary of digests used in the manifest.

    Returns:
        bool: True if all digests are present and used, False if any digests are missing or not used.
    """
    needed_digests = []
    for file in manifest_files:
        with open(file, 'r') as f:
            for line in f:
                if re.match(r'File-Checksum', line):
                    needed_digests.append(line.split()[1])

    for digest in needed_digests:
        if digest not in digests_used:
            return False

    return True

