def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("Prior must be an InventoryValidator instance")

    # check that the prior version and self have the same properties
    for prop in self.properties:
        prior_prop = prior.get(prop)

        # check that the property is present in the prior version
        if prior_prop is None:
            raise ValueError(f"Property {prop} is not present in the prior version")

        # check that the values match
        if prior_prop != self.get(prop):
            raise ValueError(f"Property {prop} has different values between the prior version and self")

    # check that the inventory objects have the same number of inventory items
    if len(self) != len(prior):
        raise ValueError("Inventories have different numbers of items")

    # check that the inventory items are the same
    for item in self:
        if item not in prior:
            raise ValueError(f"Item '{item}' is not present in the prior version")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("Prior must be of type InventoryValidator")
    if self.id != prior.id:
        raise ValueError("Prior inventory must have the same ID as the current inventory")
    if self.count != prior.count:
        raise ValueError("Prior inventory must have the same count as the current inventory")
    if self.version != prior.version - 1:
        raise ValueError("Prior inventory must have a version number one less than the current inventory")
    if set(self.annotations) != set(prior.annotations):
        raise ValueError("Prior inventory must have the same set of annotations as the current inventory")
    if set(self.data) != set(prior.data):
        raise ValueError("Prior inventory must have the same set of data as the current inventory")
    for data_key, data_value in self.data.items():
        if data_key not in prior.data:
            raise KeyError(f"Data key {data_key} does not exist in prior inventory")
        if data_value != prior.data[data_key]:
            raise ValueError(f"Data value for key {data_key} is not equal to the value in the prior inventory")
    for annotation in self.annotations:
        if annotation not in prior.annotations:
            raise KeyError(f"Annotation {annotation} does not exist in prior inventory")
        if self.annotations[annotation] != prior.annotations[annotation]:
            raise ValueError(f"Annotation value for {annotation} is not equal to the value in the prior inventory")
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for state in inventory:
        for file in state["contents"]:
            logical_path = file[0]
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(file[1])
    return logical_path_map

def get_logical_path_map(inventory, version):
    logical_paths = set()
    for component in inventory.components:
        if component.version.is_equal(version):
            for content_file in component.content_files:
                logical_paths.add(content_file.logical_path)

    logical_path_map = dict()
    for logical_path in logical_paths:
        logical_path_map[logical_path] = set()
        for version_file in inventory.versions:
            if version_file.version.is_equal(version):
                for content_file in version_file.content_files:
                    if content_file.logical_path == logical_path:
                        logical_path_map[logical_path].add(content_file)
            elif version_file.version > version:
                for content_file in version_file.content_files:
                    if content_file.logical_path == logical_path:
                        logical_path_map[logical_path].add(content_file)

    return logical_path_map

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for content_file in version.content_files:
        for logical_path in content_file.logical_paths:
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file)
    return logical_path_map

