def _group_files_by_xml_filename(source, xmls, files):
    result = {}
    for xml in xmls:
        xml_basename = os.path.basename(xml)
        result[xml_basename] = Package(os.path.join(source, xml))
    for file in files:
        file = os.path.basename(file)
        for xml_basename, package in result.items():
            if file.endswith('_' + xml_basename):
                package.add_file(file)
    return result

