def _extract_number_and_supplment_from_issue_element(issue):
    """Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.

    Valores possíveis:
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    issue = issue.strip()

    if issue[-1] == ')':
        return None, None

    number = None
    suppl = None

    for word in issue.split():
        if word.isdigit():
            if number is not None:
                return None, None
            else:
                number = int(word)
        elif word == 'suppl':
            suppl = True
        elif word == 'spe':
            if suppl:
                suppl = 'spe'
            else:
                suppl = 'spe'
        elif word == 'pr' or word == 'prl':
            suppl += 'pr'
        else:
            suppl = None

    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        print("====== pretty started =====")

    outer_indent = indent
    output = ""

    try:
        # Print object type
        output += "\n" + " " * indent + "type: " + self.__class__.__name__

        # Print object attributes
        output += "\n" + " " * indent + "attributes: "
        for attr, val in self.__dict__.items():
            if attr in ["_id", "_idx"]:
                continue
            output += "\n" + " " * indent + "    " + attr + ": "
            if isinstance(val, list):
                output += []
            elif isinstance(val, bool):
                output += str(val)
            elif isinstance(val, str):
                output += '"' + val + '"'
            else:
                output += str(val)

        # Print children
        if len(self.children) > 0:
            output += "\n" + " " * indent + "children:"
            for child in self.children:
                if hasattr(child, "pretty"):
                    output += "\n" + " " * indent + "    - " + child.pretty(indent + 2, debug)
                else:
                    output += "\n" + " " * indent + "    - " + str(child)

        # Print pretty debugging information
        if debug:
            print("====== pretty ended =====")

        return output

    except Exception as e:
        print("====== pretty failed =====")
        print(str(e))
        return output

