def _fromutc(self, dt):
    assert isinstance(dt, datetime) and dt.tzinfo is not None

    new_datetime = dt.astimezone(self.tz)
    if new_datetime.tzinfo is None:
        raise Exception("Failed to construct a timezone-aware datetime object")

    if new_datetime.tzinfo.utcoffset(new_datetime) is None:
        raise Exception("The given datetime is in a fold state")

    return new_datetime

