def tzname_in_python2(namefunc):
    """
    When Python2 and Python3 are interoperable, tzname() APIs will return
    either bytes or strings. This wrapper makes sure that no matter which
    version of Python is being used, the results of the namefunc function
    will always be passed through the appropriate decoding function.

    Use this wrapper to ensure your code that uses tzname() will work and
    return the expected result under both Python2 and Python3.
    """
    if six.PY3:
        tzname_result = namefunc()
        if isinstance(tzname_result, six.binary_type):
            return tzname_result.decode("utf-8")
        else:
            return tzname_result  # Already a string, nothing to do.

