    """Call the given command(s).

    Arguments:
        commands (List[str]): A list of command strings.
        args (List[str]): A list of command line arguments to pass to the commands.
        cwd (str, optional): The current working directory. If not specified, the current working directory will be used.
        verbose (bool, optional): Whether to print the command and its output.
        hide_stderr (bool, optional): Whether to suppress stderr output.
        env (Dict[str, str], optional): A dictionary of environment variables to set when running the command.
    """
    if not commands or not args:
        raise ValueError("No commands or args provided!")

    for command in commands:
        if not command:
            raise ValueError("Empty command string!")

        command_parts = shlex.split(command)
        if not command_parts:
            raise ValueError("Malformed command string!")

        proc = subprocess.Popen(command_parts, cwd=cwd, env=env, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL)
        out, err = proc.communicate(args=args)

        if verbose:
            logger.info(command + " " + " ".join(args))
            if out:
                logger.info(out.decode())
            if err:
                logger.warning(err.decode())

        if proc.returncode != 0:
            raise subprocess.CalledProcessError(proc.returncode, command + " " + " ".join(args))

