def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool, optional): Whether to validate individual objects in the hierarchy. Defaults to True.
        check_digests (bool, optional): Whether to check the digests of objects. Defaults to True.
        show_warnings (bool, optional): Whether to show warnings for issues found in the hierarchy. Defaults to False.

    Returns:
        num_objects (int): The number of objects in the hierarchy that were checked.
        good_objects (int): The number of objects that were found to be valid.
    """

    num_objects = 0
    good_objects = 0

    for obj in self.elements():
        num_objects += 1

        if validate_objects:
            if not obj.validate():
                if show_warnings:
                    print(f"Invalid object: {obj}")
            else:
                good_objects += 1

        if check_digests:
            if obj.digest() is None:
                if show_warnings:
                    print(f"Missing digest: {obj}")
            else:
                if not obj.digest_matches():
                    if show_warnings:
                        print(f"Invalid digest: {obj}")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # check top-level nodes
    for node in self.children:
        if not isinstance(node, StorageNode):
            raise ValueError(f"Invalid child node type: {node!r}")
        num_objects += 1
        if node.validate(validate_objects, check_digests, show_warnings):
            good_objects += 1

    # check other nodes
    for node in self.walk():
        if not isinstance(node, StorageNode):
            raise ValueError(f"Invalid node type: {node!r}")
        num_objects += 1
        if node.validate(validate_objects, check_digests, show_warnings):
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    if validate_objects:
        # Iterate over all objects in the hierarchy
        for obj in self.iterate_objects():
            num_objects += 1

            # Check that the object is valid
            if obj.is_valid():
                good_objects += 1
            else:
                # Object is not valid, print a warning
                if show_warnings:
                    print(f"WARNING: Object {obj.id} is not valid.")

    if check_digests:
        # Iterate over all objects in the hierarchy
        for obj in self.iterate_objects():
            num_objects += 1
            # Check the digest of the object
            expected_digest = obj.digest if hasattr(obj, "digest") else None
            if expected_digest is not None:
                # Check that the object's digest matches the expected digest
                if obj.digest != expected_digest:
                    # Object's digest does not match the expected digest, print a warning
                    if show_warnings:
                        print(f"WARNING: Object {obj.id} has incorrect digest. Expected: {expected_digest}, Actual: {obj.digest}")
                    else:
                        # If show_warnings is False, return the object with incorrect digest and the expected and actual digest
                        return (obj, expected_digest, obj.digest)
            else:
                # Object does not have a digest, print a warning
                if show_warnings:
                    print(f"WARNING: Object {obj.id} has no digest.")

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

