    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    # initialize counters
    num_objects = 0
    good_objects = 0

    # validate top-level elements
    for element in self.elements:
        if validate_objects:
            element.validate()
        if check_digests:
            element_digest = element.digest
            if element_digest:
                #validate digest
                element.check_digest(element_digest)
