        return '.'.join([major, minor, new_patch])

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.

    Arguments:
        version (str): a version identifier in the form X.Y.Z, where X is the major version, Y is the minor version, and Z is the patch version.

    Returns:
        str: the next version identifier after the current one.
    """
    parts = version.split(".")
    major = int(parts[0])
    minor = int(parts[1])
    patch = int(parts[2])
    if patch == 99:
        if minor == 99:
            if major == 99:
                print("Version limit reached")
                return None
            else:
                return str(major + 1) + ".0.0"
        else:
            return str(major) + "." + str(minor + 1) + ".0"
    else:
        return str(major) + "." + str(minor) + "." + str(patch + 1)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.inventories[0]
    inventories = [self.get_inventory_for_version(version_dir) for version_dir in version_dirs]

    # Check that each version has an inventory up to that point
    for inventory in inventories:
        if inventory is not None and inventory > root_inventory:
            raise ValueError("Version inventory is greater than the root inventory")

    # Keep a record of any content digests different from those in the root inventory
    # so that we can also check them when validating the content
    digests = set()
    for version_dir, inventory in enumerate(inventories, start=1):
        if inventory is not None and inventory > root_inventory:
            diff = inventory - root_inventory
            for resource in diff:
                digest = resource.content_digest
                if digest not in digests:
                    digests.add(digest)
                else:
                    raise ValueError("Duplicate content digest found in version inventory")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    inventory = self.root_inventory.copy()
    content_digests = {}

    for version_dir in version_dirs:
        version_inventory = self.get_inventory(version_dir)
        for item in version_inventory:
            name = item['name']
            digest = item['digest']
            if name in inventory:
                schema_version = inventory[name]['version']
                if schema_version != digest['version']:
                    raise ValueError(f"Digest version '{digest['version']}' does not match item '{name}' version '{schema_version}'.")
            else:
                inventory[name] = digest
                content_digests[name] = digest

    for name, digest in content_digests.items():
        for inventory in self.version_inventories.values():
            if name in inventory and inventory[name] != digest:
                raise ValueError(f"Content digest '{digest}' does not match item '{name}' digest '{inventory[name]}'.")

    return inventory

