        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        # Check for root
        if os.path.exists(os.path.join(path, "info", "root.jsonld")):
            return "root"

        # Check for object
        if os.path.exists(os.path.join(path, "info", "object-id.txt")):
            return "object"

        # Check for file, might be inventory
        for file in os.listdir(path):
            if file.startswith("0=*"):
                return "file"

        # Couldn't determine anything
        return "unknown"
    except Exception as e:
        return "error: " + str(e)

