def deep_merge_nodes(nodes):
    # If there are no nodes to merge, return an empty list
    if not nodes:
        return []

    # Create an empty dictionary to store the merged nodes
    merged_nodes = {}

    # Loop through the nodes and merge them
    for node in nodes:
        # Get the node key and value
        key, value = node[0], node[1]

        # If the node key is not already in the dictionary, store it
        if key not in merged_nodes:
            merged_nodes[key] = value
        # Otherwise, if the node value is a mapping, merge it with the existing value
        elif isinstance(value, MappingNode):
            merged_nodes[key] = MappingNode(value=dict(merged_nodes[key].value, **value.value))
            # Other values are kept (replace with depth_merge_nodes in case there are more nodes with the same key)

    # Return the merged node list
    return [t for t in merged_nodes.items()]

def deep_merge_nodes(nodes):
    result = []
    for key, value in nodes:
        # If the value is not a mapping node, keep the last one
        if not isinstance(value, ruamel.yaml.nodes.MappingNode):
            continue
        result.append((key, value))

        # If the value is a mapping node, recursively merge its children
        for child_key, child_value in value.value:
            if isinstance(child_value, ruamel.yaml.nodes.MappingNode):
                result.extend(deep_merge_nodes([(child_key, child_value)]))
    return result

