def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """

    # For each subparser, collect all its arguments
    subparser_arguments = {}
    for subparser_name, subparser in self.parser._subparsers.choices.items():
        subparser_arguments[subparser_name] = {}
        for action in subparser._actions:
            if isinstance(action, _StoreAction):
                arg_name = action.dest
                arg_value = action.default
                if arg_name in unparsed_arguments:
                    arg_value = unparsed_arguments[arg_name]
                subparser_arguments[subparser_name][arg_name] = arg_value

    # For global arguments, collect all unassigned values
    global_arguments = {}
    for action in self.parser._actions:
        if isinstance(action, _StoreAction):
            arg_name = action.dest
            arg_value = action.default
            if arg_name not in unparsed_arguments and arg_name not in subparser_arguments[arg_name]:
                global_arguments[arg_name] = arg_value

    # Reformat arguments into a dict mapping subparser names to Namespace instances
    arguments = {}
    for subparser_name in subparser_arguments:
        namespace = argparse.Namespace()
        for argument, value in subparser_arguments[subparser_name].items():
            setattr(namespace, argument, value)
        arguments[subparser_name] = namespace

    # Add the global arguments to the global Namespace
    global_namespace = argparse.Namespace()
    for argument, value in global_arguments.items():
        setattr(global_namespace, argument, value)
    arguments["global"] = global_namespace

    return arguments

