    give each requested action's subparser a shot at parsing all arguments. This allows common arguments
    like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parser_map = { p.name: p for p in subparsers.values() }
    namespace_dict = {}
    unclaimed_args = []
    while unparsed_arguments:
        arg = unparsed_arguments[0]
        if arg.startswith('-'):
            for p in parser_map.values():
                if arg in p.prefix_chars:
                    if not p.nargs:
                        unparsed_arguments.pop(0)
                        if arg == '--help':
                            raise SystemExit(0)
                        args = [ arg ]
                    else:
                        args = unparsed_arguments[:p.nargs]
                        unparsed_arguments[:p.nargs] = []
                    try:
                        namespace = p.parse_args(args)
                    except SystemExit as e:
                        if p.name != 'main':
                            raise
                        if e.args[0] == 2:
                            print('Use --help for available options')
                        else:
                            print('Error: {}'.format(e))
                        raise SystemExit(e.args[0])
                    unclaimed_args = unparsed_arguments
                    return (namespace_dict, unclaimed_args)
                else:
                    unclaimed_args.append(arg)
        else:
            unclaimed_args.append(arg)
    return (namespace_dict, unclaimed_args)

