def paging(response, max_results):
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    if not isinstance(response, list):
        raise ValueError("response must be a list")

    if len(response) == 0:
        return ()

    pages = [(0, max_results)]
    remaining = len(response)

    while remaining > 0:
        pages.append((remaining, remaining))
        remaining -= max_results

    index = 0
    for start, end in pages:
        index += 1
        yield response[start:end]

    if index != len(pages):
        raise ValueError("Unexpected response length")

def paging(response, max_results):
    for offset in range(0, len(response), max_results):
        yield response[offset:offset + max_results]

def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """

    suffixes = ('B', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y')
    multiplier = 1024
    # Loop to handle first case, which is when user input just number
    for suffix in suffixes:
        if size.endswith(suffix):
            num = float(size[:-1])
            multiplier = multiplier ** 10
            return math.floor(num * multiplier)

    # Handle second case when user input is string of numbers '500'
    if size.isdigit():
        return int(size)

    raise ValueError("File size value is expected as '500' or '500K', but found: " + size)

