def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    result = []
    for v in vertices:
        for i in range(3):
            if i == 0:
                result.append((v, (v + 1) % len(vertices), (v + 2) % len(vertices)))
            else:
                result.append(((v + 1) % len(vertices), v, (v + 2) % len(vertices)))
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and (number < 0 or number >= len(alphabet)):
        raise ValueError("Number out of range")
    if padding is not None and number < 0:
        result = "-" + int_to_string(-number, alphabet, padding - 1)
    else:
        result = ""
        while number > 0:
