def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()
    code_blocks = 0

    for line in text.splitlines():
        if line.strip().startswith(''):
            code_blocks += 1
            continue
        if code_blocks % 2 == 1:
            continue

        for tag in _find_tag_words(line):
            tags.add(tag)
            if replacer is not None:
                line = line.replace(tag, replacer(tag))

    return tags, line

def _find_tag_words(line: str) -> Iterable[str]:
    """Returns all tag words found in the given line."""

    # Treat HTML tags as a word boundary
    pattern = r'\b(?:<[^>]+>|[^\w\s])'

    return re.findall(pattern, line, flags=re.IGNORECASE)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    replaced_text = text
    in_code_block = False
    for i in range(len(text)):
        char = text[i]
        if char == '`':
            in_code_block = not in_code_block
        elif not in_code_block and char in '#-':
            if i + 1 < len(text) and text[i + 1] == '(':
                j = find_close_paren(text, i + 1)
                if j is None:
                    break
                tag = text[i + 2:j]
                tags.add(tag)
                if replacer is not None:
                    replaced_text = replaced_text.replace('#' + tag + ')', replacer(tag), 1)
            else:
                tag = text[i + 1]
                tags.add(tag)
                if replacer is not None:
                    replaced_text = replaced_text.replace('#' + tag, replacer(tag), 1)
    return tags, replaced_text

