def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict (dict): The dict of parsing directives
    """
    for key, value in parser_dict.items():
        if key.startswith("include"):
            if key.startswith("include+"):
                for sub_key, sub_value in value.items():
                    if sub_key not in self.parser_dict:
                        self.parser_dict[sub_key] = sub_value
            else:
                self.parser_dict[key] = value

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Arguments:
        parser_dict (dict): The dictionary of parsed spec files

    Loops through the parser_dict and replaces the references to included files with their content.
    """
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    self._include_groups(item)

    for ref, value in parser_dict.items():
        if not os.path.isabs(value):
            ref_path = os.path.dirname(ref)
            value = os.path.join(ref_path, value)
            with open(value, 'r') as f:
                content = f.read()
                parser_dict[ref] = content

