    Args:
        self (classes.AbstractElement): The AbstractElement instance.

    Returns:
        The resolved arguments' values as a dictionary.
    """
    # We'll start by making a copy of the defaults dict
    resolved_default_values = self.spec["defaults"].copy()

    # Next, we'll go through each of the resolved dependencies and fill in the defaults with the appropriate values
    for resolved_dependency in self.resolved_dependencies:
        if resolved_dependency in self.spec["defaults"]:
            for resolved_default_key, resolved_default_value in self.spec["defaults"].items():
                if resolved_default_value in resolved_dependency.resolved_defaults:
                    resolved_default_values[resolved_dependency] = resolved_dependency.resolved_defaults[resolved_default_value]

    # Finally, we'll trim any unused keys from the resolved defaults dict
    return {
        key: value
        for key, value in resolved_default_values.items()
        if key in resolved_dependency.spec["configuration"]
    }

