        if spec_option.get("default") is not None:
            argument.default = spec_option["default"]

        argument.allow_empty = spec_option.get("allow_empty", False)
        argument.meta = spec_option.get("meta", {})
        argument.element_type = type_class
        complex_inst[option_name] = argument

        return complex_inst

